-- ============================================================
-- REAL MOTOR DATA SEED SCRIPT
-- All max_thrust values stored in kg
-- ============================================================

BEGIN;

-- 1. Ensure categories exist (insert if not already present by name)
INSERT INTO public.categories (name, description)
  SELECT '1kg Class', 'Lightweight motors up to 1kg thrust. Ideal for 3-5" freestyle/racing FPV drones and micro UAVs.'
  WHERE NOT EXISTS (SELECT 1 FROM public.categories WHERE name = '1kg Class');

INSERT INTO public.categories (name, description)
  SELECT '2kg Class', 'Mid-range motors 1–2kg thrust. Suited for 5-7" long-range FPV builds and light payload drones.'
  WHERE NOT EXISTS (SELECT 1 FROM public.categories WHERE name = '2kg Class');

INSERT INTO public.categories (name, description)
  SELECT '5kg Class', 'Heavy-lift motors 3–5kg thrust. For professional aerial photography, survey drones, and light commercial UAV platforms.'
  WHERE NOT EXISTS (SELECT 1 FROM public.categories WHERE name = '5kg Class');

INSERT INTO public.categories (name, description)
  SELECT '10kg Class', 'Industrial motors 6–10kg thrust. Used in heavy-lift hexacopters, octocopters, and professional cargo UAV systems.'
  WHERE NOT EXISTS (SELECT 1 FROM public.categories WHERE name = '10kg Class');

INSERT INTO public.categories (name, description)
  SELECT '15kg Class', 'Ultra heavy-lift motors 10–15kg thrust. For agricultural spraying drones, heavy cargo delivery, and industrial inspection UAVs.'
  WHERE NOT EXISTS (SELECT 1 FROM public.categories WHERE name = '15kg Class');

INSERT INTO public.categories (name, description)
  SELECT '20kg+ Class', 'Maximum thrust motors exceeding 15kg. For the largest commercial UAV platforms, heavy industrial drones, and next-generation aerial systems.'
  WHERE NOT EXISTS (SELECT 1 FROM public.categories WHERE name = '20kg+ Class');

INSERT INTO public.categories (name, description)
  SELECT 'Other Class', 'Specialty motors including gimbal motors, servos, and non-standard applications.'
  WHERE NOT EXISTS (SELECT 1 FROM public.categories WHERE name = 'Other Class');

-- 2. Helper: build a lookup for category IDs
-- 3. Insert all real motors

-- NOTE: max_thrust stored in kg (converted from grams where applicable)

INSERT INTO public.motors (
  category_id, motor_name, company, max_thrust,
  recommended_esc, recommended_propeller,
  link_motor, link_esc, link_propeller,
  custom_parameters
)
