  ON c.name = m.cat_name;

COMMIT;

SELECT 
  cat.name as category,
  count(m.id) as motor_count
FROM public.motors m
JOIN public.categories cat ON m.category_id = cat.id
GROUP BY cat.name
ORDER BY cat.name;
